sys_ui_action.script:
if (!gs.hasRole('x_travel_buddy_app.Admin') && current.assigned_to != gs.getUserID()) {
    gs.addErrorMessage('Only the assigned Buddy or an Admin can approve this trip request.');
    current.setAbortAction(true);
} else if (current.state != 1) {
    gs.addErrorMessage('Only trip requests in Pending Approval can be approved.');
    current.setAbortAction(true);
} else {
    var buddyId = current.getValue('assigned_to');
    var schedGr = new GlideRecord('cmn_schedule');
    schedGr.addQuery('x_travel_buddy_app_u_buddy_profile', buddyId);
    schedGr.query();
    if (!schedGr.next()) {
        gs.addErrorMessage('This Buddy does not have a schedule set up yet. Please contact an admin.');
        current.setAbortAction(true);
    } else {
        var span = new GlideRecord('cmn_schedule_span');
        span.initialize();
        span.schedule = schedGr.getUniqueValue();
        span.type = 'Booked';
        span.u_start_date_time = current.getValue('start_time');
        span.u_end_date_time = current.getValue('end_time');
        span.x_travel_buddy_app_u_linked_trip = current.sys_id;
        span.name = 'Trip ' + current.getValue('number');
        var spanId = span.insert();

        if (!spanId) {
            gs.addErrorMessage('Could not book this trip - the buddy already has an overlapping booked trip.');
            current.setAbortAction(true);
        } else {
            current.state = 2;
            current.update();

            try {
                var travelerId = current.getValue('u_traveler');
                if (travelerId) {
                    var travelerGr = new GlideRecord('sys_user');
                    if (travelerGr.get(travelerId)) {
                        var toAddr = travelerGr.getValue('email');
                        if (toAddr) {
                            var emailGr = new GlideRecord('sys_email');
                            emailGr.initialize();
                            emailGr.type = 'send-ready';
                            emailGr.state = 'ready';
                            emailGr.recipients = toAddr;
                            emailGr.content_type = 'text/plain';
                            emailGr.subject = 'Travel Buddy: Your trip request was approved - ' + current.getDisplayValue('number');
                            emailGr.body = 'Hi ' + travelerGr.getDisplayValue('first_name') + ',\n\n' +
                                'Good news! Your trip request ' + current.getDisplayValue('number') + ' has been approved and booked.\n\n' +
                                '- Travel Buddy App';
                            emailGr.insert();
                        }
                    }
                }
            } catch (e) {
                gs.error('TBA approve notification failed: ' + e.message);
            }

            gs.addInfoMessage('Trip approved and booked on the Buddy\'s schedule.');
            action.setRedirectURL(current);
        }
    }
}
